                symbol = "💎";
            } else {
                symbol = "💮";
            }
            title = symbol + "〖" + text + "〗" + symbol;
            url = `${href},{"webView":true}`
            list.push({   
                title: title,
                isVip: vip,
                url: url
            });
        });
    }
}
